			function getToday() {
			    var date = new Date();
			    var year = date.getFullYear();
			    var month = ("0" + (1 + date.getMonth())).slice(-2);
			    var day = ("0" + date.getDate()).slice(-2);

			    return year + month + day;
			}

			function getMinusOneMonth() {
			    var date = new Date();
			    date.setDate(date.getDate() - 30);
			    var year = date.getFullYear();
			    var month = ("0" + (1 + date.getMonth())).slice(-2);
			    var day = ("0" + date.getDate()).slice(-2);

			    return year + month + day;
			}


